import { type CnOptions, cn as mergeClasses } from "tailwind-variants";

export function cn(...classes: CnOptions): string {
  return mergeClasses(...classes) ?? "";
}

"use client";

import {
  Toolbar as AriaToolbar,
  composeRenderProps,
  SeparatorContext,
  ToggleButtonGroupContext,
  type ToolbarProps,
} from "react-aria-components";
import { cn } from "./utils";

export function Toolbar({ className, ...props }: ToolbarProps) {
  const orientation = props.orientation ?? "horizontal";
  return (
    <ToggleButtonGroupContext.Provider value={{ orientation }}>
      <SeparatorContext.Provider
        value={{
          orientation: orientation === "horizontal" ? "vertical" : "horizontal",
        }}
      >
        <AriaToolbar
          {...props}
          data-slot="toolbar"
          className={composeRenderProps(className, (className) =>
            cn(
              "flex w-fit max-w-full flex-wrap items-center gap-1.5 rounded-lg border border-border bg-card p-1.5 shadow-[var(--shadow-card)] data-[orientation=vertical]:flex-col data-[orientation=vertical]:items-stretch [&_[data-slot=toggle-button-group]]:border-0 [&_[data-slot=toggle-button-group]]:bg-transparent [&_[data-slot=toggle-button-group]]:p-0",
              className,
            ),
          )}
        />
      </SeparatorContext.Provider>
    </ToggleButtonGroupContext.Provider>
  );
}

"use client";

import { type HTMLMotionProps, motion, useReducedMotion } from "motion/react";
import {
  ToggleButton as AriaToggleButton,
  composeRenderProps,
  type ToggleButtonProps,
} from "react-aria-components";
import { tv, type VariantProps } from "tailwind-variants";

const toggleButtonStyles = tv({
  base: "inline-flex min-h-11 cursor-pointer items-center justify-center gap-2 rounded-md px-4 text-sm font-medium data-[disabled]:cursor-default data-[disabled]:opacity-50 data-[focus-visible]:z-10 data-[focus-visible]:outline-2 data-[focus-visible]:outline-offset-2 data-[focus-visible]:outline-ring",
  variants: {
    variant: {
      default:
        "border border-border bg-card text-foreground shadow-[var(--shadow-card)] hover:bg-muted data-[pressed]:bg-muted data-[selected]:border-primary/40 data-[selected]:bg-accent data-[selected]:text-accent-foreground",
      segmented:
        "min-h-11 border border-transparent bg-transparent px-3 sm:min-h-9 text-muted-foreground shadow-none hover:bg-card/70 hover:text-foreground data-[pressed]:bg-card/70 data-[selected]:border-border data-[selected]:bg-card data-[selected]:text-foreground data-[selected]:shadow-[var(--shadow-card)]",
      ghost:
        "border border-transparent bg-transparent text-foreground hover:bg-muted data-[pressed]:bg-muted data-[selected]:bg-accent data-[selected]:text-accent-foreground",
    },
  },
  defaultVariants: { variant: "default" },
});

export interface ToggleButtonStyleProps extends ToggleButtonProps {
  variant?: NonNullable<VariantProps<typeof toggleButtonStyles>["variant"]>;
}

export function ToggleButton({
  className,
  variant = "default",
  ...props
}: ToggleButtonStyleProps) {
  const reduceMotion = useReducedMotion();
  return (
    <AriaToggleButton
      {...props}
      data-slot="toggle-button"
      data-variant={variant}
      render={
        props.render ??
        ((domProps) => (
          <motion.button
            {...(domProps as HTMLMotionProps<"button">)}
            whileTap={
              reduceMotion || props.isDisabled ? undefined : { scale: 0.96 }
            }
            transition={{ duration: 0.14 }}
          />
        ))
      }
      className={composeRenderProps(className, (className) =>
        toggleButtonStyles({ variant, className }),
      )}
    />
  );
}

"use client";

import {
  ToggleButtonGroup as AriaToggleButtonGroup,
  composeRenderProps,
  type ToggleButtonGroupProps,
} from "react-aria-components";
import { cn } from "./utils";

export function ToggleButtonGroup({
  className,
  ...props
}: ToggleButtonGroupProps) {
  return (
    <AriaToggleButtonGroup
      {...props}
      data-slot="toggle-button-group"
      className={composeRenderProps(className, (className) =>
        cn(
          "inline-flex w-fit max-w-full flex-wrap gap-1 rounded-lg border border-border bg-secondary p-1 data-[orientation=vertical]:flex-col",
          className,
        ),
      )}
    />
  );
}

import { tv, type VariantProps } from "tailwind-variants";

export const buttonStyles = tv({
  base: "inline-flex shrink-0 cursor-default items-center justify-center gap-2 whitespace-nowrap rounded-md font-medium tracking-[-0.01em] data-[disabled]:cursor-default data-[disabled]:opacity-50 data-[disabled]:shadow-none data-[focus-visible]:outline-2 data-[focus-visible]:outline-offset-3 data-[focus-visible]:outline-ring",
  variants: {
    variant: {
      default:
        "bg-primary text-primary-foreground shadow-[var(--shadow-card)] hover:bg-primary/90 data-[pressed]:bg-primary/90",
      secondary:
        "bg-secondary text-secondary-foreground hover:bg-border/70 data-[pressed]:bg-border/70",
      outline:
        "border border-border bg-card text-foreground shadow-[var(--shadow-card)] hover:bg-muted data-[pressed]:bg-muted",
      ghost: "text-foreground hover:bg-muted data-[pressed]:bg-muted",
      destructive:
        "bg-destructive text-background shadow-[var(--shadow-card)] hover:bg-destructive/90 data-[pressed]:bg-destructive/90",
      nav: "text-foreground hover:bg-muted aria-[pressed=true]:bg-accent aria-[pressed=true]:text-accent-foreground aria-[pressed=true]:hover:bg-accent",
    },
    size: {
      default: "h-11 px-5 text-sm",
      sm: "h-9 px-3.5 text-sm",
      lg: "h-12 px-6 text-sm",
      icon: "size-11 cursor-pointer p-0",
      nav: "h-9 w-full justify-center px-0 text-xs sm:justify-start sm:px-2.5",
    },
  },
  defaultVariants: { variant: "default", size: "default" },
});

export const buttonLinkStyles = tv({
  extend: buttonStyles,
  base: "cursor-pointer",
});

export type ButtonVariant = NonNullable<
  VariantProps<typeof buttonStyles>["variant"]
>;
export type ButtonSize = NonNullable<VariantProps<typeof buttonStyles>["size"]>;

"use client";

import { type MotionProps, motion, useReducedMotion } from "motion/react";
import {
  Button as AriaButton,
  type ButtonProps as AriaButtonProps,
  composeRenderProps,
} from "react-aria-components";
import {
  type ButtonSize,
  type ButtonVariant,
  buttonStyles,
} from "./button-styles";

export interface ButtonProps
  extends Omit<
    AriaButtonProps,
    | "style"
    | "onAnimationStart"
    | "onAnimationEnd"
    | "onAnimationIteration"
    | "onHoverStart"
    | "onHoverEnd"
  > {
  ref?: React.Ref<HTMLButtonElement>;
  variant?: ButtonVariant;
  size?: ButtonSize;
  static?: boolean;
  layout?: MotionProps["layout"];
}

const MotionButton = motion.create(AriaButton);

export function Button({
  className,
  variant = "default",
  size = "default",
  static: isStatic = false,
  layout,
  ...props
}: ButtonProps) {
  const reduceMotion = useReducedMotion();
  return (
    <MotionButton
      data-slot="button"
      data-variant={variant}
      data-size={size}
      layout={reduceMotion ? false : layout}
      whileTap={isStatic || reduceMotion ? undefined : { scale: 0.96 }}
      transition={{ duration: 0.14, ease: [0.23, 1, 0.32, 1] }}
      className={composeRenderProps(className, (className) =>
        buttonStyles({ variant, size, className }),
      )}
      {...props}
    />
  );
}

"use client";

import {
  Separator as AriaSeparator,
  type SeparatorProps,
} from "react-aria-components";
import { tv } from "tailwind-variants";

const separatorStyles = tv({
  base: "shrink-0 border-0 bg-border forced-colors:bg-[ButtonBorder]",
  variants: {
    orientation: {
      horizontal: "h-px w-full",
      vertical: "w-px self-stretch",
    },
  },
  defaultVariants: { orientation: "horizontal" },
});

export function Separator({
  className,
  orientation = "horizontal",
  ...props
}: SeparatorProps) {
  return (
    <AriaSeparator
      {...props}
      data-slot="separator"
      orientation={orientation}
      className={separatorStyles({ orientation, className })}
    />
  );
}
